import sys,json,re,html,shutil;sys.path.insert(0,'/home/claude/pao2')
import story as S, story_art2 as B
from playwright.sync_api import sync_playwright
def load(f,v):
    t=open(f'/home/claude/pack/sbpack/src/games/storyBuilder/{f}').read();return json.loads(t[t.index('= ')+2:].rstrip().rstrip(';'))
ANIM={
'pigs':['Mother waves and hearts float up; the pigs bob and wave with their bundles.','Straw, stick and brick houses grow up one after another while the pigs bounce.','The wolf huffs, wind streaks blow, the straw house tips over and fades.','The stick house collapses while two pigs run toward the brick house.','The wolf puffs and the brick house only shakes a little; sparkles glint.','The wolf wobbles on the roof, steam rises from the pot, the pig waits with a spoon.','Hearts rise, the pigs bob together, and the wolf trots far away.'],
'goldi':['Steam rises from the three bowls while the bears walk out the door.','Goldilocks walks up the path, a bubble knocks twice, the door is open.','Steam, a snowflake and sparkles show hot, cold and just right.','The little chair wobbles and drops its pieces while Goldilocks shakes and says Oops.','The bears\' beds sit in a row while Goldilocks breathes and Zs float up.','The bears bob in, Baby Bear points, an exclamation mark pops up.','Goldilocks runs away across the meadow while the bears wave from the door.'],
'tort':['The hare bobs proudly, sparkles twinkle around him, a bluebird flaps.','The hare shakes with laughter and the tortoise slides in slowly.','A rooster counts 3, 2, 1, GO! one number at a time.','The hare dashes out of sight with dust puffs; the tortoise plods on, eyes on the road.','The hare breathes in his sleep, Zs float up, the tortoise creeps along far away.','The tortoise tiptoes past the sleeping hare; a shh bubble pops up.','The sun sets, the tape breaks, sparkles and a Winner bubble pop as the hare runs in late.']}
STORIES={}
for k,f,v in [('pigs','pigsSteps.js','PIGS_STEPS'),('goldi','goldilocksSteps.js','GOLDILOCKS_STEPS'),('tort','tortoiseSteps.js','TORTOISE_STEPS')]:
    st=load(f,v);STORIES[k]=[{'n':s['key'],'q':s['question'],'t':s['narration'],'a':', '.join(o['label'] for o in s['options'] if o['correct']),'m':ANIM[k][i]} for i,s in enumerate(st)]
STORIES['red']=[{'n':s[0],'q':s[1],'t':s[2],'a':s[3],'m':s[4]} for s in S.STEPS]
ORDER=['red','pigs','goldi','tort']
def svg(k,i): return re.sub(r'<style>.*?</style>','',B.scene(k,i),flags=re.S)
def live():
    sc={k:[svg(k,i) for i in range(len(STORIES[k]))] for k in ORDER}
    titles={k:B.STORIES[k]['title'] for k in ORDER}
    css=('*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;background:linear-gradient(180deg,#5BB8F0,#9AD8F8 40%,#D6F0FF);min-height:100vh;color:#1B2B6B}h1,h2,h3,.p{font-family:Poppins,Inter,sans-serif}'
      '.wrap{max-width:1400px;margin:0 auto;padding:28px 28px 60px}.top{text-align:center;color:#fff}.top .k{font-size:13px;font-weight:800;letter-spacing:.16em}.top h1{margin:2px 0;font-size:40px;text-shadow:0 3px 0 rgba(20,60,140,.3)}.top p{margin:0;font-weight:600;color:#EAF6FF}'
      '.tabs{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:18px 0 0}.tab{border:0;border-radius:999px;padding:10px 20px;font-family:Poppins;font-weight:800;font-size:15px;cursor:pointer;background:#fff;color:#4B2BB8;box-shadow:0 4px 0 #C4D5F2}.tab.on{background:linear-gradient(180deg,#8B6BF0,#6B47E0);color:#fff;box-shadow:0 5px 0 #4B2BB8}'
      '.card{background:#fff;border-radius:30px;box-shadow:0 14px 40px rgba(24,70,130,.18);padding:10px}.player{display:grid;grid-template-columns:1.25fr 1fr;gap:22px;margin:22px 0 26px}.stage{border-radius:24px;overflow:hidden;aspect-ratio:1.6;position:relative}.stage>svg{width:100%;height:100%}'
      '.info{padding:14px 12px;display:flex;flex-direction:column;gap:12px}.step{font-weight:800;font-size:13px;letter-spacing:.12em;color:#5B3FD0}.q{font-size:28px;font-weight:800;line-height:1.2}.t{font-size:18px;font-weight:600;color:#475875;line-height:1.45}.ans{background:#E3F8EA;color:#15803D;font-weight:800;border-radius:14px;padding:10px 14px}.mo{background:#EEF3FF;color:#3B3F9F;font-weight:700;border-radius:14px;padding:10px 14px}'
      '.ctl{display:flex;gap:10px;margin-top:auto;flex-wrap:wrap}.btn{height:48px;padding:0 20px;border-radius:16px;font-family:Poppins;font-weight:800;font-size:16px;cursor:pointer;background:#fff;color:#4B2BB8;box-shadow:0 4px 0 #C4D5F2;border:3px solid #D3E1F8}.btn.main{background:linear-gradient(180deg,#8B6BF0,#6B47E0);color:#fff;border:0;box-shadow:0 5px 0 #4B2BB8}'
      '.dots{display:flex;gap:8px;flex-wrap:wrap}.dot{width:36px;height:36px;border-radius:50%;border:3px solid #CFE0F5;background:#E8F1FC;font-family:Poppins;font-weight:800;color:#8A97AE;cursor:pointer}.dot.on{background:#FFB020;border-color:#FFB020;color:#3B2400;box-shadow:0 0 0 4px rgba(255,176,32,.35)}.dot.done{background:#22C55E;border-color:#22C55E;color:#fff}'
      '.bar{height:8px;border-radius:4px;background:#E3ECFA;overflow:hidden}.bar i{display:block;height:100%;width:0;background:#6366F1}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.cell{cursor:pointer}.cell .s{border-radius:22px;overflow:hidden;aspect-ratio:1.6;position:relative}.cell .s svg{width:100%;height:100%;display:block}.cell h3{margin:10px 6px 0;font-size:17px}.cell p{margin:4px 6px 8px;font-size:13.5px;color:#475875;font-weight:600}'
      '.paused .sb *{animation-play-state:paused!important}@media(max-width:900px){.player{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}}')
    js=('const S='+json.dumps(sc)+',D='+json.dumps(STORIES)+',TT='+json.dumps(titles)+',O='+json.dumps(ORDER)+';let k="red",i=0,auto=true,t0=0,MS=6500;const $=id=>document.getElementById(id);'
      'function tabs(){$("tabs").innerHTML=O.map(x=>`<button class="tab ${x==k?"on":""}" data-k="${x}">${TT[x]}</button>`).join("");document.querySelectorAll(".tab").forEach(b=>b.onclick=()=>{k=b.dataset.k;grid();show(0)})}'
      'function grid(){$("grid").innerHTML=D[k].map((d,j)=>`<div class="card cell" data-j="${j}"><div class="s">${S[k][j]}</div><h3>${j+1}. ${d.n}</h3><p>${d.q}</p></div>`).join("");document.querySelectorAll(".cell").forEach(c=>c.onclick=()=>{show(+c.dataset.j);scrollTo({top:0,behavior:"smooth"})})}'
      'function show(n){const N=D[k].length;i=(n+N)%N;const d=D[k][i];$("stage").innerHTML=S[k][i];$("title").textContent=TT[k]+", live storyboard";$("step").textContent="STEP "+(i+1)+" OF "+N+" · "+d.n.toUpperCase();$("q").textContent=d.q;$("t").textContent=d.t;$("a").textContent="Right answer: "+d.a;$("m").textContent="Animation: "+d.m;'
      '$("dots").innerHTML=D[k].map((x,j)=>`<button class="dot ${j==i?"on":j<i?"done":""}" data-j="${j}">${j+1}</button>`).join("");document.querySelectorAll(".dot").forEach(b=>b.onclick=()=>show(+b.dataset.j));tabs();t0=performance.now()}'
      '$("prev").onclick=()=>show(i-1);$("next").onclick=()=>show(i+1);$("play").onclick=()=>{auto=!auto;$("play").textContent=auto?"Pause":"Play";document.body.classList.toggle("paused",!auto);if(auto)t0=performance.now()};'
      'grid();show(0);function tick(now){if(auto){const p=(now-t0)/MS;$("bar").style.width=Math.min(100,p*100)+"%";if(p>=1)show(i+1)}requestAnimationFrame(tick)}requestAnimationFrame(tick);')
    return ('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Story Builder live storyboards</title><style>'+B.ALLKF+css+'</style></head><body><div class="wrap"><div class="top"><div class="k">STORY BUILDER</div><h1 id="title"></h1><p>Pick a story, press Play to watch every step, or tap any scene. Questions and answers are samples.</p></div><div class="tabs" id="tabs"></div>'
      '<div class="player card"><div class="stage" id="stage"></div><div class="info"><div class="step" id="step"></div><div class="q" id="q"></div><div class="t" id="t"></div><div class="ans" id="a"></div><div class="mo" id="m"></div><div class="bar"><i id="bar"></i></div><div class="dots" id="dots"></div><div class="ctl"><button class="btn" id="prev">Back</button><button class="btn main" id="play">Pause</button><button class="btn" id="next">Next</button></div></div></div><div class="grid" id="grid"></div></div><script>'+js+'</script></body></html>')
def board(k):
    st=STORIES[k];n=len(st);cols=3 if n==9 else 4
    full=' '.join(s['t'] for s in st)
    cards=''.join(f'<div style="background:#fff;border-radius:26px;padding:10px;box-shadow:0 10px 30px rgba(24,70,130,.16)"><div style="border-radius:18px;overflow:hidden;aspect-ratio:1.6;position:relative">{B.scene(k,i)}<div style="position:absolute;left:10px;bottom:10px;background:#FFB020;color:#3B2400;font-family:Poppins;font-weight:800;border-radius:999px;padding:3px 12px;font-size:14px">{i+1}</div></div><div style="padding:8px 6px 4px"><div style="font-family:Poppins;font-weight:800;font-size:17px;color:#4B2BB8">{html.escape(s["n"])}</div><div style="font-size:13.5px;font-weight:600;line-height:1.45;color:#334155;margin-top:4px">{html.escape(s["t"])}</div><div style="margin-top:8px;font-size:13px;font-weight:800;color:#1B2B6B">{html.escape(s["q"])}</div><div style="margin-top:6px;background:#E3F8EA;color:#15803D;font-weight:800;font-size:12.5px;border-radius:10px;padding:6px 10px">Answer: {html.escape(s["a"])}</div><div style="margin-top:6px;background:#EEF3FF;color:#3B3F9F;font-weight:700;font-size:12px;border-radius:10px;padding:6px 10px">Animation: {html.escape(s["m"])}</div></div></div>' for i,s in enumerate(st))
    return (f'<html><head><meta charset="utf-8"><style>*{{box-sizing:border-box}}body{{margin:0}}</style></head><body><div style="width:1440px;padding:36px 40px 44px;font-family:Inter;background:linear-gradient(180deg,#5BB8F0,#9AD8F8 30%,#D6F0FF);color:#1B2B6B">'
      f'<div style="text-align:center;color:#fff"><div style="font-size:13px;font-weight:800;letter-spacing:.16em">STORY BUILDER STORYBOARD</div><div style="font-family:Poppins;font-weight:800;font-size:42px;text-shadow:0 3px 0 rgba(20,60,140,.3)">{html.escape(B.STORIES[k]["title"])}</div><div style="font-weight:600;color:#EAF6FF">{n} animated steps. Scenes loop about every 6 seconds. Questions and answers are samples.</div></div>'
      f'<div style="background:#fff;border-radius:26px;padding:18px 24px;margin:22px 0;box-shadow:0 10px 30px rgba(24,70,130,.16)"><div style="font-family:Poppins;font-weight:800;color:#5B3FD0;font-size:15px;letter-spacing:.08em">THE FULL STORY</div><div style="font-size:16px;font-weight:600;line-height:1.55;color:#334155;margin-top:6px">{html.escape(full)}</div></div>'
      f'<div style="display:grid;grid-template-columns:repeat({cols},1fr);gap:20px">{cards}</div></div></body></html>')
if __name__=='__main__':
    open('/home/claude/pack/story-builder-storyboard-live.html','w').write(live())
    names={'red':'288-story-builder-storyboard-little-red-riding-hood','pigs':'289-story-builder-storyboard-three-little-pigs','goldi':'290-story-builder-storyboard-goldilocks','tort':'291-story-builder-storyboard-tortoise-and-hare'}
    with sync_playwright() as p:
        b=p.chromium.launch();pg=b.new_page(viewport={'width':1440,'height':900},device_scale_factor=1)
        for k in ORDER:
            pg.set_content(board(k));pg.wait_for_timeout(400);pg.evaluate("document.getAnimations().forEach(a=>{a.pause();a.currentTime=3000})")
            pg.screenshot(path=f'/home/claude/pngs/{names[k]}.png',full_page=True)
        pg.set_viewport_size({'width':1440,'height':900});pg.goto('file:///home/claude/pack/story-builder-storyboard-live.html');pg.wait_for_timeout(600)
        pg.click('text=The Tortoise and the Hare');pg.wait_for_timeout(500);pg.screenshot(path='/tmp/live.png');print(pg.evaluate("document.querySelectorAll('.cell').length"))
        b.close()
